// the fieldSchema that domain declared (if any) is a SEPARATE, narrower
// concern handled by `validateDomainFields` below — mirroring how this
// function checks `work.workflowStep` is one of the domain's Workflow steps above
// without opening a per-step schema engine of its own.
if (touched('domainFields') && work.domainFields !== undefined && work.domainFields !== null) {
  if (typeof work.domainFields !== 'object' || Array.isArray(work.domainFields)) {
    throw new WorkValidationError(
      `work.domainFields must be a plain object ({ [domainName]: {...} }) when present, got: ${JSON.stringify(work.domainFields)}`,
    );
  }
  for (const [domainName, fields] of Object.entries(work.domainFields)) {
    if (!fields || typeof fields !== 'object' || Array.isArray(fields)) {
      throw new WorkValidationError(
        `work.domainFields.${domainName} must be a plain object when present, got: ${JSON.stringify(fields)}`,
      );
    }
  }

/**
 * Validate that every `mergeAfter` target of `work` points at an id present
 * in `existingIds` — mirrors `validateDeps` exactly, for the same reason
 * (D5, docs/history/tsk-3bn-merge-conductor-harness-v2/CONTEXT.md): a
 * dangling merge-order target is a real, catchable mistake, unlike
 * `parent`/`discoveredFrom`'s deliberately-unchecked dangling case. A
 * no-op when `mergeAfter` is absent.
 */
export function validateMergeAfter(work, existingIds) {
  if (!Array.isArray(work.mergeAfter)) return true;
  const known = existingIds instanceof Set ? existingIds : new Set(existingIds ?? []);
  for (const target of work.mergeAfter) {
    if (!known.has(target)) {
      throw new WorkValidationError(`work "${work.id}" has mergeAfter target "${target}", which is not a known id.`);
    }
  }
  return true;
}

// Path-like substring: at least one "/" separator and a file extension,
// e.g. "docs/history/foo/CONTEXT.md" or "src/state/work.mjs". Deliberately
// excludes a bare filename with no directory separator (e.g. "work.mjs"
// alone) -- requiring a directory segment cuts down on false positives
// against ordinary prose ("e.g.", "v1.2", etc.).
const PATH_LIKE_TOKEN = /[\w.-]+(?:\/[\w.-]+)+\.[\w-]+/g;

// worker-slots.mjs — the worker-slot ledger: how many work items are running
// right now, and whether there is room to start another. PURE: no fs, no
// `.fgos/` read, same discipline as plan-pool.mjs/cleanup-pool.mjs/
// frontier.mjs — every caller folds the view itself and hands it in.
//
// The concept is a "worker slot", never "executor": docs/decisions/0026:73-87
// already locked that word for a narrower, unrelated thing (a subTask-scale
// helper unit, not a rootTask lifecycle) and says explicitly that the two do
// not merge.
//
// Two faces, deliberately separate (docs/history/orchestrator-worker-slots/
// plan.md §Shape T1):
//
//   - the read-only face a launcher asks BEFORE it stands a worker up —
//     herdr-dashboard opening a pane, fgos-fanout firing an Agent. Cheap, holds
//     nothing, reserves nothing. Those two reach it through `fgos slots`
//     rather than by importing this file: one is Rust and one is prose, and
//     decision 0014 makes the CLI the door.
//   - the enforcing face, called inside claimWork so no claim path can slip
//     past even if a future launcher forgets to ask first.
//
// Both are needed. claimWork only runs AFTER a worker is already standing
// (herdr opens a pane -> claude boots -> /fgOS:discover-next -> take/pick),
// so an enforcing gate alone would cost a whole pane to learn "no room"; a
// pre-check alone would miss any claim path that skips the launcher.
//
// The race between the two faces is accepted on purpose (plan.md): between
// "asked, saw room" and "actually claimed" another launcher can take the last
// slot. No reservation or TTL is added to close it, so a launcher must treat
// a grant as advice and a refusal as final — the enforcing face is the one
// that decides, and it never lets `occupied` exceed `ceiling`.

